1	// Feed navigation renders synthetic time buckets, not the folder tree.
2	import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
3	import { useCallback } from "react";
4	import { useShallow } from "zustand/react/shallow";
5	
6	import { useEditor } from "@/features/notes/editor/hooks/editor-context";
7	import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
8	import { type DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
9	import { useSelection } from "@/app/state/selection-store";
10	import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
11	import { focusNoScroll } from "@/shared/lib/dom";
12	import { computeRangeSelection } from "@/shared/lib/selection";
13	import { TreeNode } from "./tree-node";
14	
15	type FeedPanelProps = {
16	  paneBodyRef: RefObject<HTMLDivElement | null>;
17	  onNavigateToNotes?: () => void;
18	  onPaneClick?: () => void;
19	  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
20	  onOpenContextMenu: (state: DesktopContextMenuState) => void;
21	};
22	
23	export function FeedPanel({
24	  paneBodyRef,
25	  onNavigateToNotes,
26	  onPaneClick,
27	  onPaneKeyDown,
28	  onOpenContextMenu,
29	}: FeedPanelProps) {
30	  const { clearDraft, clearNote } = useEditor();
31	  const {
32	    feedTreeData,
33	    feedNodeById,
34	    activeFeedGroup,
35	    setActiveFeedGroup,
36	    expanded,
37	    setExpanded,
38	    allNotePreviews,
39	    feedLoading,
40	    shouldNestNotesInNavigation,
41	  } = useNotesTree();
42	  const {
43	    setSelectedFolders,
44	    setLastSelectedFolder,
45	    setActiveFolder,
46	    selectedNotes,
47	    setSelectedNotes,
48	    lastSelectedNote,
49	    setLastSelectedNote,
50	    setActiveNote,
51	  } = useSelection(
52	    useShallow((state) => ({
53	      setSelectedFolders: state.setSelectedFolders,
54	      setLastSelectedFolder: state.setLastSelectedFolder,
55	      setActiveFolder: state.setActiveFolder,
56	      selectedNotes: state.selectedNotes,
57	      setSelectedNotes: state.setSelectedNotes,
58	      lastSelectedNote: state.lastSelectedNote,
59	      setLastSelectedNote: state.setLastSelectedNote,
60	      setActiveNote: state.setActiveNote,
61	    }))
62	  );
63	
64	  const selectFeedGroup = useCallback(
65	    (groupId: string) => {
66	      onNavigateToNotes?.();
67	      setActiveFeedGroup(groupId);
68	      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
69	      setLastSelectedFolder(FEED_FOLDER_PATH);
70	      setActiveFolder(FEED_FOLDER_PATH);
71	      setSelectedNotes(new Set());
72	      setLastSelectedNote("");
73	      setActiveNote(null);
74	      clearDraft();
75	      clearNote();
76	      focusNoScroll(paneBodyRef.current);
77	    },
78	    [
79	      clearDraft,
80	      clearNote,
81	      onNavigateToNotes,
82	      paneBodyRef,
83	      setActiveFeedGroup,
84	      setActiveFolder,
85	      setActiveNote,
86	      setLastSelectedFolder,
87	      setLastSelectedNote,
88	      setSelectedFolders,
89	      setSelectedNotes,
90	    ]
91	  );
92	
93	  const handleNoteSelect = useCallback(
94	    (notePath: string, event: ReactMouseEvent, parentPath: string) => {
95	      onNavigateToNotes?.();
96	      const parentNode = feedNodeById.get(parentPath);
97	      const notePaths = parentNode?.notes.map((note) => note.path) || [];
98	      setSelectedNotes(
99	        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
100	      );
101	      setLastSelectedNote(notePath);
102	      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
103	      setLastSelectedFolder(FEED_FOLDER_PATH);
104	      setActiveFolder(FEED_FOLDER_PATH);
105	      setActiveFeedGroup(parentPath);
106	      setActiveNote(notePath);
107	      if (shouldNestNotesInNavigation) {
108	        focusNoScroll(paneBodyRef.current);
109	      }
110	    },
111	    [
112	      feedNodeById,
113	      lastSelectedNote,
114	      onNavigateToNotes,
115	      paneBodyRef,
116	      selectedNotes,
117	      setActiveFeedGroup,
118	      setActiveFolder,
119	      setActiveNote,
120	      setLastSelectedFolder,
121	      setLastSelectedNote,
122	      setSelectedFolders,
123	      setSelectedNotes,
124	      shouldNestNotesInNavigation,
125	    ]
126	  );
127	
128	  const handleToggle = useCallback(
129	    (event: ReactMouseEvent, id: string) => {
130	      event.stopPropagation();
131	      setExpanded((prev) => {
132	        const next = new Set(prev);
133	        if (next.has(id)) {
134	          next.delete(id);
135	        } else {
136	          next.add(id);
137	        }
138	        return next;
139	      });
140	    },
141	    [setExpanded]
142	  );
143	
144	  const handleNoteContextMenu = useCallback(
145	    (event: ReactMouseEvent, notePath: string, parentPath: string) => {
146	      event.preventDefault();
147	      event.stopPropagation();
148	      const parentNode = feedNodeById.get(parentPath);
149	      const notePaths = parentNode?.notes.map((note) => note.path) || [];
150	      const targetPaths =
151	        selectedNotes.size > 1 && selectedNotes.has(notePath) ? Array.from(selectedNotes) : [notePath];
152	      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
153	      setLastSelectedFolder(FEED_FOLDER_PATH);
154	      setActiveFolder(FEED_FOLDER_PATH);
155	      if (!selectedNotes.has(notePath)) {
156	        setSelectedNotes(new Set([notePath]));
157	        setLastSelectedNote(notePath);
158	      }
159	      setActiveFeedGroup(parentPath);
160	      setActiveNote(notePath);
161	      focusNoScroll(paneBodyRef.current);
162	      onOpenContextMenu({
163	        kind: "note",
164	        x: event.clientX,
165	        y: event.clientY,
166	        path: notePath,
167	        parentPath,
168	        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
169	      });
170	    },
171	    [
172	      feedNodeById,
173	      onOpenContextMenu,
174	      paneBodyRef,
175	      selectedNotes,
176	      setActiveFeedGroup,
177	      setActiveFolder,
178	      setActiveNote,
179	      setLastSelectedFolder,
180	      setLastSelectedNote,
181	      setSelectedFolders,
182	      setSelectedNotes,
183	    ]
184	  );
185	
186	  if (feedTreeData.length === 0) {
187	    return (
188	      <div className="empty">
189	        {feedLoading ? "Loading feed..." : "No feed notes yet."}
190	      </div>
191	    );
192	  }
193	
194	  return (
195	    <div
196	      className="nav-scroll-area"
197	      ref={paneBodyRef}
198	      tabIndex={0}
199	      onKeyDown={onPaneKeyDown}
200	      onClick={(event) => {
201	        if (onPaneClick) {
202	          onPaneClick();
203	        }
204	        if (event.target === event.currentTarget) {
205	          selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
206	        }
207	      }}
208	    >
209	      <div className="pane-body tree-root feed-navigation-tree">
210	        {feedTreeData.map((node) => (
211	          <TreeNode
212	            key={node.id}
213	            node={node}
214	            depth={0}
215	            selectedIds={activeFeedGroup ? new Set([activeFeedGroup]) : new Set()}
216	            selectedNoteIds={selectedNotes}
217	            showNotesAsChildren={shouldNestNotesInNavigation}
218	            edgeSnap={null}
219	            expanded={expanded}
220	            feedMode
221	            onSelect={(event, id) => {
222	              event.stopPropagation();
223	              selectFeedGroup(id);
224	            }}
225	            onToggle={handleToggle}
226	            onNoteSelect={handleNoteSelect}
227	            onNoteContextMenu={handleNoteContextMenu}
228	            notePreviews={allNotePreviews}
229	            onContextMenu={(event, id) => {
230	              event.preventDefault();
231	              event.stopPropagation();
232	              selectFeedGroup(id);
233	            }}
234	            indentationWidth={18}
235	            draggable={false}
236	          />
237	        ))}
238	      </div>
239	    </div>
240	  );
241	}
