1	import type { FolderNode } from "@typenotes/shared/types";
2	import type { TreeItem } from "./types";
3	import { flattenTree } from "./dnd-tree";
4	import { DROP_PREFIX, ROOT_ID } from "./tree-dnd";
5	
6	// Pure tree transforms used by navigation state and drag-and-drop. Keeping
7	// them side-effect free makes ordering, selection, and tests easier to follow.
8	export function buildTreeItems(node: FolderNode): TreeItem[] {
9	  return node.children.map((child) => ({
10	    id: child.path,
11	    name: child.name,
12	    noteCount: child.notes.length,
13	    notes: child.notes,
14	    children: buildTreeItems(child),
15	  }));
16	}
17	
18	export type FlatNode = {
19	  id: string;
20	  name: string;
21	  parentId: string | null;
22	  depth: number;
23	};
24	
25	export const flattenTreeData = (
26	  nodes: TreeItem[],
27	  parentId: string | null = null,
28	  depth = 0,
29	  acc: FlatNode[] = []
30	) => {
31	  nodes.forEach((node) => {
32	    acc.push({ id: node.id, name: node.name, parentId, depth });
33	    if (node.children && node.children.length > 0) {
34	      flattenTreeData(node.children, node.id, depth + 1, acc);
35	    }
36	  });
37	  return acc;
38	};
39	
40	export const arraysEqual = (a: string[] | undefined, b: string[] | undefined) => {
41	  if (a === b) {
42	    return true;
43	  }
44	  if (!a || !b || a.length !== b.length) {
45	    return false;
46	  }
47	  for (let i = 0; i < a.length; i += 1) {
48	    if (a[i] !== b[i]) {
49	      return false;
50	    }
51	  }
52	  return true;
53	};
54	
55	export const buildFolderOrderMap = (
56	  nodes: TreeItem[],
57	  parentId: string | null,
58	  map: Record<string, string[]>
59	) => {
60	  map[parentId ?? ""] = nodes.map((node) => node.id.split("/").pop() || node.id);
61	  nodes.forEach((node) => buildFolderOrderMap(node.children, node.id, map));
62	};
63	
64	export const applyFolderOrder = (
65	  node: FolderNode,
66	  orderMap: Record<string, string[]>
67	): FolderNode => {
68	  const key = node.path || "";
69	  const order = orderMap[key];
70	  let children = node.children;
71	  if (order && order.length > 0) {
72	    const index = new Map(order.map((name, idx) => [name, idx]));
73	    children = [...children].sort((a, b) => {
74	      const ai = index.get(a.name);
75	      const bi = index.get(b.name);
76	      if (ai == null && bi == null) {
77	        return a.name.localeCompare(b.name);
78	      }
79	      if (ai == null) {
80	        return 1;
81	      }
82	      if (bi == null) {
83	        return -1;
84	      }
85	      return ai - bi;
86	    });
87	  }
88	  return {
89	    ...node,
90	    children: children.map((child) => applyFolderOrder(child, orderMap)),
91	  };
92	};
93	
94	export const findParentAndIndex = (
95	  nodes: TreeItem[],
96	  id: string,
97	  parentId: string | null = null
98	): { parentId: string | null; index: number } | null => {
99	  for (let index = 0; index < nodes.length; index += 1) {
100	    const node = nodes[index];
101	    if (node.id === id) {
102	      return { parentId, index };
103	    }
104	    if (node.children && node.children.length > 0) {
105	      const result = findParentAndIndex(node.children, id, node.id);
106	      if (result) {
107	        return result;
108	      }
109	    }
110	  }
111	  return null;
112	};
113	
114	export const getNodeById = (nodes: TreeItem[], id: string): TreeItem | null => {
115	  for (const node of nodes) {
116	    if (node.id === id) {
117	      return node;
118	    }
119	    if (node.children && node.children.length > 0) {
120	      const found = getNodeById(node.children, id);
121	      if (found) {
122	        return found;
123	      }
124	    }
125	  }
126	  return null;
127	};
128	
129	export const removeNodes = (nodes: TreeItem[], ids: string[]) => {
130	  const idSet = new Set(ids);
131	  const removed: TreeItem[] = [];
132	
133	  const walk = (list: TreeItem[]) => {
134	    const next: TreeItem[] = [];
135	    list.forEach((node) => {
136	      if (idSet.has(node.id)) {
137	        removed.push(node);
138	        return;
139	      }
140	      let children = node.children || [];
141	      if (children.length > 0) {
142	        const updatedChildren = walk(children);
143	        if (updatedChildren !== children) {
144	          children = updatedChildren;
145	        }
146	      }
147	      if (children !== node.children) {
148	        next.push({ ...node, children });
149	      } else {
150	        next.push(node);
151	      }
152	    });
153	    return next;
154	  };
155	
156	  return { tree: walk(nodes), removed };
157	};
158	
159	export const insertNodes = (
160	  nodes: TreeItem[],
161	  parentId: string | null,
162	  index: number,
163	  items: TreeItem[]
164	): TreeItem[] => {
165	  if (parentId === null) {
166	    const before = nodes.slice(0, index);
167	    const after = nodes.slice(index);
168	    return [...before, ...items, ...after];
169	  }
170	
171	  let changed = false;
172	  const next = nodes.map((node) => {
173	    if (node.id === parentId) {
174	      changed = true;
175	      const children = node.children ? [...node.children] : [];
176	      const before = children.slice(0, index);
177	      const after = children.slice(index);
178	      return { ...node, children: [...before, ...items, ...after] };
179	    }
180	    if (node.children && node.children.length > 0) {
181	      const updatedChildren = insertNodes(node.children, parentId, index, items);
182	      if (updatedChildren !== node.children) {
183	        changed = true;
184	        return { ...node, children: updatedChildren };
185	      }
186	    }
187	    return node;
188	  });
189	
190	  return changed ? next : nodes;
191	};
192	
193	export type DropTarget =
194	  | { type: "root"; position: "inside" }
195	  | { type: "item"; itemId: string; position: "inside" | "before" | "after" };
196	
197	export const parseDropTargetId = (id: string | number | null): DropTarget | null => {
198	  if (typeof id !== "string") {
199	    return null;
200	  }
201	  const parts = id.split(":");
202	  if (parts.length !== 3 || parts[0] !== DROP_PREFIX) {
203	    return null;
204	  }
205	  const itemId = parts[1];
206	  const position = parts[2];
207	  if (
208	    !itemId ||
209	    !position ||
210	    (position !== "inside" && position !== "before" && position !== "after")
211	  ) {
212	    return null;
213	  }
214	  if (itemId === ROOT_ID) {
215	    return position === "inside" ? { type: "root", position } : null;
216	  }
217	  return { type: "item", itemId, position };
218	};
219	
220	export const sortIdsByTreeOrder = (ids: string[], orderedIds: string[]) => {
221	  const orderIndex = new Map<string, number>();
222	  orderedIds.forEach((id, index) => {
223	    orderIndex.set(id, index);
224	  });
225	  return ids.slice().sort((a, b) => (orderIndex.get(a) ?? 0) - (orderIndex.get(b) ?? 0));
226	};
227	
228	export const isDescendantOf = (
229	  nodes: TreeItem[],
230	  ancestorId: string,
231	  targetId: string
232	) => {
233	  const ancestor = getNodeById(nodes, ancestorId);
234	  if (!ancestor || !ancestor.children || ancestor.children.length === 0) {
235	    return false;
236	  }
237	  const stack = [...ancestor.children];
238	  while (stack.length > 0) {
239	    const current = stack.pop();
240	    if (current?.id === targetId) {
241	      return true;
242	    }
243	    if (current?.children && current.children.length > 0) {
244	      stack.push(...current.children);
245	    }
246	  }
247	  return false;
248	};
249	
250	export const isInDraggedSubtree = (
251	  nodes: TreeItem[],
252	  draggedIds: string[],
253	  targetId: string
254	) => {
255	  return draggedIds.some(
256	    (draggedId) => draggedId === targetId || isDescendantOf(nodes, draggedId, targetId)
257	  );
258	};
259	
260	export const getTopLevelSelected = (
261	  selectedIds: string[],
262	  parentById: Record<string, string | null>
263	) => {
264	  const selectedSet = new Set(selectedIds);
265	  return selectedIds.filter((id) => {
266	    let parent = parentById[id];
267	    while (parent) {
268	      if (selectedSet.has(parent)) {
269	        return false;
270	      }
271	      parent = parentById[parent];
272	    }
273	    return true;
274	  });
275	};
276	
277	export function findNode(node: FolderNode | null, path: string): FolderNode | null {
278	  if (!node) {
279	    return null;
280	  }
281	  if (node.path === path) {
282	    return node;
283	  }
284	  for (const child of node.children) {
285	    const match = findNode(child, path);
286	    if (match) {
287	      return match;
