221	  // Folder drops: reparent / reorder the dragged folder subtree, then persist
222	  // the moves + per-parent folder order and refresh if any parent changed.
223	  const handleFolderDragEnd = useCallback(
224	    async (event: DragEndEvent) => {
225	      const { over } = event;
226	
227	      setActiveId(null);
228	      setEdgeSnap(null);
229	      document.body.style.setProperty("cursor", "");
230	      dragStartPoint.current = null;
231	      activeDrag.current = null;
232	      if (expandTimeoutRef.current) {
233	        window.clearTimeout(expandTimeoutRef.current);
234	        expandTimeoutRef.current = null;
235	      }
236	      expandTargetRef.current = null;
237	
238	      if (!over) return;
239	
240	      const resolvedId =
241	        edgeSnap ? `${DROP_PREFIX}:${edgeSnap.id}:${edgeSnap.position}` : over.id;
242	      const dropTarget = parseDropTargetId(resolvedId);
243	      if (!dropTarget) {
244	        logGroup("drop ignored", { reason: "invalid target", overId: over.id });
245	        return;
246	      }
247	
248	      const selectedIdsList = Array.from(selectedFolders);
249	      const draggingIds = getTopLevelSelected(selectedIdsList, parentById);
250	      if (draggingIds.length === 0) {
251	        logGroup("drop ignored", { reason: "no dragging ids" });
252	        return;
253	      }
254	
255	      if (dropTarget.type === "item" && draggingIds.includes(dropTarget.itemId)) {
256	        logGroup("drop ignored", { reason: "target is dragged item", target: dropTarget });
257	        return;
258	      }
259	
260	      if (
261	        dropTarget.type === "item" &&
262	        isInDraggedSubtree(treeData, draggingIds, dropTarget.itemId)
263	      ) {
264	        logGroup("drop ignored", {
265	          reason: "target inside dragged subtree",
266	          target: dropTarget,
267	        });
268	        return;
269	      }
270	
271	      const orderedDraggingIds = sortIdsByTreeOrder(draggingIds, orderedIds);
272	      if (orderedDraggingIds.some(isSystemFolder)) {
273	        logGroup("drop ignored", { reason: "system folder drag blocked" });
274	        return;
275	      }
276	      // Optimistic local rebuild: pull the dragged subtrees out, then splice
277	      // them back in at the resolved target before persisting to the backend.
278	      const { tree: prunedTree, removed } = removeNodes(treeData, orderedDraggingIds);
279	      const removedMap = new Map(removed.map((node) => [node.id, node]));
280	      const nodesToInsert = orderedDraggingIds
281	        .map((id) => removedMap.get(id))
282	        .filter(Boolean) as TreeItem[];
283	
284	      if (nodesToInsert.length === 0) return;
285	
286	      let targetParentId: string | null = null;
287	      let targetIndex = 0;
288	
289	      if (dropTarget.type === "root") {
290	        targetParentId = null;
291	        targetIndex = prunedTree.length;
292	      } else if (dropTarget.position === "inside") {
293	        targetParentId = dropTarget.itemId;
294	        const parentNode = getNodeById(prunedTree, dropTarget.itemId);
295	        targetIndex = parentNode?.children?.length ?? 0;
296	      } else {
297	        const position = findParentAndIndex(prunedTree, dropTarget.itemId);
298	        if (!position) return;
299	        targetParentId = position.parentId;
300	        targetIndex = position.index + (dropTarget.position === "after" ? 1 : 0);
