331	      const noteOrderMap: Record<string, string[]> = {};
332	      buildNoteOrderMap(tree, noteOrderMap);
333	
334	      const currentOrderMap: Record<string, string[]> = {};
335	      const nextOrderMap: Record<string, string[]> = {};
336	      buildFolderOrderMap(treeData, null, currentOrderMap);
337	      buildFolderOrderMap(nextTree, null, nextOrderMap);
