10	type UseKeyboardNavigationArgs = {
11	  layoutMode: string;
12	  appMode: AppMode;
13	  shouldNestNotesInNavigation: boolean;
14	  sidebarCollapsed: boolean;
15	  increaseEditorFontSize: () => void;
16	  decreaseEditorFontSize: () => void;
