24	  orderedIds: string[];
25	  flatItemById: Map<string, FlattenedItem>;
26	  expanded: Set<string>;
27	  setExpanded: React.Dispatch<React.SetStateAction<Set<string>>>;
28	  visibleNavigationItems: VisibleNavigationItem[];
29	  activeNavigationTab: "feed" | "folders";
30	  feedVisibleNavigationItems: VisibleNavigationItem[];
31	  feedNodeById: Map<string, FeedTreeNode>;
32	  // Selection state
33	  activeFolder: string;
34	  lastSelectedFolder: string;
35	  setSelectedFolders: React.Dispatch<React.SetStateAction<Set<string>>>;
36	  setLastSelectedFolder: (path: string) => void;
37	  setActiveFolder: (path: string) => void;
38	  activeNote: string | null;
39	  lastSelectedNote: string;
40	  setSelectedNotes: React.Dispatch<React.SetStateAction<Set<string>>>;
41	  setLastSelectedNote: (path: string) => void;
42	  setActiveNote: (path: string | null) => void;
43	  notes: Array<{ path: string }>;
44	  activeFeedGroup: string;
45	  setActiveFeedGroup: (path: string) => void;
46	  // Refs
47	  foldersPanelRef: React.RefObject<HTMLDivElement | null>;
48	  middlePaneRef: React.RefObject<HTMLDivElement | null>;
49	  rightPaneRef: React.RefObject<HTMLDivElement | null>;
50	  notesPanelRef: React.RefObject<HTMLDivElement | null>;
51	};
52	
53	export function useKeyboardNavigation({
54	  layoutMode,
55	  appMode,
56	  shouldNestNotesInNavigation,
57	  sidebarCollapsed,
58	  increaseEditorFontSize,
59	  decreaseEditorFontSize,
60	  resetEditorFontSize,
61	  createNewNote,
62	  deleteSelectedNotes,
63	  lockAppNow,
64	  setSidebarCollapsed,
65	  visibleItems,
66	  orderedIds,
67	  flatItemById,
68	  expanded,
69	  setExpanded,
70	  visibleNavigationItems,
71	  activeNavigationTab,
72	  feedVisibleNavigationItems,
73	  feedNodeById,
74	  activeFolder,
75	  lastSelectedFolder,
76	  setSelectedFolders,
77	  setLastSelectedFolder,
78	  setActiveFolder,
79	  activeNote,
80	  lastSelectedNote,
81	  setSelectedNotes,
82	  setLastSelectedNote,
83	  setActiveNote,
84	  notes,
85	  activeFeedGroup,
86	  setActiveFeedGroup,
87	  foldersPanelRef,
88	  middlePaneRef,
89	  rightPaneRef,
90	  notesPanelRef,
91	}: UseKeyboardNavigationArgs) {
92	  const { clearDraft, clearNote } = useEditor();
93	  const lastLeftPaneFocusRef = useRef<"folders" | "middle">("middle");
94	
95	  usePaneShortcuts({
96	    layoutMode,
97	    appMode,
98	    shouldNestNotesInNavigation,
99	    sidebarCollapsed,
100	    increaseEditorFontSize,
101	    decreaseEditorFontSize,
102	    resetEditorFontSize,
103	    createNewNote,
104	    deleteSelectedNotes,
105	    lockAppNow,
106	    setSidebarCollapsed,
107	    foldersPanelRef,
108	    middlePaneRef,
109	    rightPaneRef,
110	    lastLeftPaneFocusRef,
111	  });
112	  const handleFeedKeyboardNavigation = useFeedKeyboardNavigation({
113	    shouldNestNotesInNavigation,
114	    feedVisibleNavigationItems,
115	    feedNodeById,
116	    expanded,
117	    setExpanded,
118	    activeFeedGroup,
119	    setActiveFeedGroup,
120	    activeNote,
121	    lastSelectedFolder,
122	    lastSelectedNote,
123	    setSelectedFolders,
124	    setLastSelectedFolder,
125	    setActiveFolder,
126	    setSelectedNotes,
127	    setLastSelectedNote,
128	    setActiveNote,
129	    clearDraft,
130	    clearNote,
131	    foldersPanelRef,
132	  });
133	
134	  // -- Notes list keyboard handler
135	  const handleNotesKeyDown = useCallback(
136	    (event: React.KeyboardEvent<HTMLDivElement>) => {
137	      if (event.key !== "ArrowUp" && event.key !== "ArrowDown") {
138	        if ((event.metaKey || event.ctrlKey) && event.key === "ArrowLeft") {
139	          event.preventDefault();
140	          lastLeftPaneFocusRef.current = "folders";
141	          focusNoScroll(foldersPanelRef.current);
142	        }
143	        return;
144	      }
145	      if (notes.length === 0) return;
146	      event.preventDefault();
147	      const notePaths = notes.map((n) => n.path);
148	      const current =
149	        lastSelectedNote && notePaths.includes(lastSelectedNote)
150	          ? lastSelectedNote
151	          : activeNote || notePaths[0];
152	      const currentIndex = notePaths.indexOf(current);
153	      const delta = event.key === "ArrowUp" ? -1 : 1;
154	      const nextIndex = Math.max(0, Math.min(notePaths.length - 1, currentIndex + delta));
155	      const nextPath = notePaths[nextIndex];
156	      setSelectedNotes(new Set([nextPath]));
157	      setLastSelectedNote(nextPath);
158	      setActiveNote(nextPath);
159	      requestAnimationFrame(() => {
160	        scrollIntoViewIfNeeded(
161	          notesPanelRef.current,
162	          `[data-note="${escapeSelectorValue(nextPath)}"]`
163	        );
164	      });
165	    },
166	    [activeNote, foldersPanelRef, lastSelectedNote, notes, notesPanelRef, setActiveNote, setLastSelectedNote, setSelectedNotes]
167	  );
168	
169	  // -- Folders keyboard handler
170	  const handleFoldersKeyDown = useCallback(
171	    (event: React.KeyboardEvent<HTMLDivElement>) => {
172	      if ((event.metaKey || event.ctrlKey) && event.key === "ArrowRight") {
173	        event.preventDefault();
174	        if (appMode === "notes" && shouldNestNotesInNavigation) {
175	          const editorElement =
176	            rightPaneRef.current?.querySelector<HTMLElement>(
177	              ".tiptap-content[contenteditable='true']"
178	            ) || rightPaneRef.current;
179	          focusNoScroll(editorElement);
180	        } else {
181	          lastLeftPaneFocusRef.current = "middle";
182	          focusNoScroll(middlePaneRef.current);
183	        }
184	        return;
185	      }
186	      if (
187	        event.key !== "ArrowUp" &&
188	        event.key !== "ArrowDown" &&
189	        event.key !== "ArrowLeft" &&
190	        event.key !== "ArrowRight"
191	      )
192	        return;
193	      if (activeNavigationTab === "feed") {
194	        handleFeedKeyboardNavigation(event);
195	        return;
196	      }
197	
198	      if (shouldNestNotesInNavigation) {
199	        if (visibleNavigationItems.length === 0) return;
200	        event.preventDefault();
201	
202	        const navIds = visibleNavigationItems.map((item) => item.id);
203	        const current =
204	          lastSelectedNote && navIds.includes(lastSelectedNote)
205	            ? lastSelectedNote
206	            : lastSelectedFolder && navIds.includes(lastSelectedFolder)
207	              ? lastSelectedFolder
208	              : activeNote && navIds.includes(activeNote)
209	                ? activeNote
210	                : activeFolder && navIds.includes(activeFolder)
211	                  ? activeFolder
212	                  : navIds[0];
213	        const currentIndex = navIds.indexOf(current);
214	        const currentEntry = visibleNavigationItems[currentIndex];
215	        if (!currentEntry) return;
216	
217	        const selectFolder = (folderPath: string) => {
218	          setSelectedFolders(new Set([folderPath]));
219	          setLastSelectedFolder(folderPath);
220	          setActiveFolder(folderPath);
221	          setSelectedNotes(new Set());
222	          setLastSelectedNote("");
223	          setActiveNote(null);
224	          clearDraft();
225	          clearNote();
226	          focusNoScroll(foldersPanelRef.current);
227	          requestAnimationFrame(() => {
228	            scrollIntoViewIfNeeded(
229	              foldersPanelRef.current,
230	              `[data-folder="${escapeSelectorValue(folderPath)}"]`
231	            );
232	          });
233	        };
234	
235	        const selectNote = (notePath: string, parentPath: string) => {
236	          setSelectedFolders(new Set(parentPath ? [parentPath] : []));
237	          setLastSelectedFolder(parentPath);
238	          setActiveFolder(parentPath);
239	          setSelectedNotes(new Set([notePath]));
240	          setLastSelectedNote(notePath);
241	          setActiveNote(notePath);
242	          focusNoScroll(foldersPanelRef.current);
243	          requestAnimationFrame(() => {
244	            scrollIntoViewIfNeeded(
245	              foldersPanelRef.current,
246	              `[data-note="${escapeSelectorValue(notePath)}"]`
247	            );
248	          });
249	        };
250	
251	        if (event.key === "ArrowUp" || event.key === "ArrowDown") {
252	          const delta = event.key === "ArrowUp" ? -1 : 1;
253	          const nextIndex = Math.max(
254	            0,
255	            Math.min(visibleNavigationItems.length - 1, currentIndex + delta)
256	          );
257	          const nextEntry = visibleNavigationItems[nextIndex];
258	          if (!nextEntry) return;
259	          if (nextEntry.type === "folder") {
260	            selectFolder(nextEntry.id);
261	            return;
262	          }
263	          selectNote(nextEntry.id, nextEntry.parentId);
264	          return;
265	        }
266	
267	        if (event.key === "ArrowRight") {
268	          if (currentEntry.type !== "folder") return;
269	          const folderItem = flatItemById.get(currentEntry.id);
270	          const noteCount = folderItem?.notes?.length || 0;
271	          const childCount = folderItem?.children.length || 0;
272	          const hasNestedItems = childCount > 0 || noteCount > 0;
273	          if (!hasNestedItems) return;
274	          if (!expanded.has(currentEntry.id)) {
275	            setExpanded((prev) => {
276	              const next = new Set(prev);
277	              next.add(currentEntry.id);
278	              return next;
279	            });
280	            return;
281	          }
282	          const firstChildEntry = visibleNavigationItems[currentIndex + 1];
283	          if (!firstChildEntry || firstChildEntry.parentId !== currentEntry.id) return;
284	          if (firstChildEntry.type === "folder") {
285	            selectFolder(firstChildEntry.id);
286	            return;
287	          }
288	          selectNote(firstChildEntry.id, firstChildEntry.parentId);
289	          return;
290	        }
291	
292	        if (event.key === "ArrowLeft") {
293	          if (currentEntry.type === "note") {
294	            selectFolder(currentEntry.parentId);
295	            return;
296	          }
297	
298	          const folderItem = flatItemById.get(currentEntry.id);
299	          const noteCount = folderItem?.notes?.length || 0;
300	          const childCount = folderItem?.children.length || 0;
301	          const hasNestedItems = childCount > 0 || noteCount > 0;
302	          if (hasNestedItems && expanded.has(currentEntry.id)) {
303	            setExpanded((prev) => {
304	              const next = new Set(prev);
305	              next.delete(currentEntry.id);
306	              return next;
307	            });
308	            return;
309	          }
310	          const parentFolderId = currentEntry.parentId;
311	          if (!parentFolderId) return;
312	          setExpanded((prev) => {
313	            const next = new Set(prev);
314	            next.delete(parentFolderId);
315	            return next;
316	          });
317	          selectFolder(parentFolderId);
318	        }
319	        return;
320	      }
321	
322	      if (visibleItems.length === 0) return;
323	      event.preventDefault();
324	
325	      const current =
326	        lastSelectedFolder && orderedIds.includes(lastSelectedFolder)
327	          ? lastSelectedFolder
328	          : activeFolder || orderedIds[0];
329	      const currentIndex = orderedIds.indexOf(current);
330	      const currentItem = visibleItems.find((item) => item.id === current);
331	      const parentId = currentItem?.parentId ?? null;
332	      const hasChildren = currentItem ? currentItem.children.length > 0 : false;
333	      const isExpanded = current ? expanded.has(current) : false;
334	
335	      if (event.key === "ArrowUp" || event.key === "ArrowDown") {
336	        const delta = event.key === "ArrowUp" ? -1 : 1;
337	        const nextIndex = Math.max(
338	          0,
339	          Math.min(orderedIds.length - 1, currentIndex + delta)
340	        );
341	        const nextPath = orderedIds[nextIndex];
342	        setSelectedFolders(new Set([nextPath]));
343	        setLastSelectedFolder(nextPath);
344	        setActiveFolder(nextPath);
345	        setSelectedNotes(new Set());
346	        setLastSelectedNote("");
347	        setActiveNote(null);
348	        clearDraft();
349	        clearNote();
350	        requestAnimationFrame(() => {
351	          scrollIntoViewIfNeeded(
352	            foldersPanelRef.current,
353	            `[data-folder="${escapeSelectorValue(nextPath)}"]`
354	          );
355	        });
356	        return;
357	      }
358	
359	      if (event.key === "ArrowRight") {
360	        if (currentItem && hasChildren) {
361	          if (!isExpanded) {
362	            setExpanded((prev) => {
363	              const next = new Set(prev);
364	              next.add(currentItem.id);
365	              return next;
366	            });
367	            return;
368	          }
369	          const firstChild = currentItem.children[0];
370	          if (firstChild) {
371	            setSelectedFolders(new Set([firstChild.id]));
372	            setLastSelectedFolder(firstChild.id);
373	            setActiveFolder(firstChild.id);
374	            setSelectedNotes(new Set());
375	            setLastSelectedNote("");
376	            setActiveNote(null);
377	            clearDraft();
378	            clearNote();
379	            requestAnimationFrame(() => {
380	              scrollIntoViewIfNeeded(
381	                foldersPanelRef.current,
382	                `[data-folder="${escapeSelectorValue(firstChild.id)}"]`
383	              );
384	            });
385	          }
386	        }
387	        return;
388	      }
389	
390	      if (event.key === "ArrowLeft") {
391	        if (currentItem && hasChildren && isExpanded) {
392	          setExpanded((prev) => {
393	            const next = new Set(prev);
394	            next.delete(currentItem.id);
395	            return next;
396	          });
397	          return;
398	        }
399	        if (parentId) {
400	          setExpanded((prev) => {
401	            const next = new Set(prev);
402	            next.delete(parentId);
403	            return next;
404	          });
405	          setSelectedFolders(new Set([parentId]));
406	          setLastSelectedFolder(parentId);
407	          setActiveFolder(parentId);
408	          setSelectedNotes(new Set());
409	          setLastSelectedNote("");
410	          setActiveNote(null);
411	          clearDraft();
412	          clearNote();
413	          requestAnimationFrame(() => {
414	            scrollIntoViewIfNeeded(
415	              foldersPanelRef.current,
416	              `[data-folder="${escapeSelectorValue(parentId)}"]`
417	            );
418	          });
419	        }
420	      }
421	    },
422	    [
423	      activeFolder,
424	      activeNote,
425	      activeFeedGroup,
426	      activeNavigationTab,
427	      appMode,
428	      clearDraft,
429	      clearNote,
